mapper.select:

    	WITH tab AS (
    		SELECT * FROM dual
    	)

    	, id_tab AS (

    		SELECT #{id} id FROM dual

    	)


    	, orderNo_tab AS (

    		SELECT #{orderNo} orderNo FROM dual

    	)


    	SELECT 

		       ,'FALSE' IS_ADD_NEW
    	  FROM T_GLUE_SCHEDULE_RESULT
    	 WHERE del_flag = '0'

    	   AND id in (
    	          SELECT id FROM id_tab
    	       )


    	   AND ORDER_NO in (
    	          SELECT orderNo FROM orderNo_tab
    	       )


    	   AND SCHEDULE_DATE = #{params.scheduleDate}


    	   AND MIX_AREA = #{params.mixArea}


    	   AND MACHINE_CODE = #{params.machineCode}


    	   AND RELEASE_STATUS = #{params.releaseStatus}


    	   AND PUBLISH_SUCCESS_COUNT >= #{params.publishSuccessCount}


    	   AND GLUE = #{params.glue}

